CREATE TABLE IF NOT EXISTS batches(id TEXT PRIMARY KEY,owner TEXT NOT NULL,tool_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',total INTEGER NOT NULL DEFAULT 0,completed INTEGER NOT NULL DEFAULT 0,failed INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_batches_owner ON batches(owner,created_at DESC);
CREATE TABLE IF NOT EXISTS batch_items(id TEXT PRIMARY KEY,batch_id TEXT NOT NULL,item_index INTEGER NOT NULL,prompt TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',work_id TEXT,attempts INTEGER NOT NULL DEFAULT 0,error TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_batch_items_batch ON batch_items(batch_id,item_index);
